import math
from pathlib import Path

import openpyxl
from openpyxl import Workbook


INPUT_XLSX = Path("/root/dye_demand_sheet.xlsx")
OUT_PLAN_XLSX = Path("/root/dye_catch_up_plan.xlsx")
OUT_SUMMARY_TXT = Path("/root/dye_catch_up_summary.txt")


def _norm(v):
    if v is None:
        return ""
    return str(v).strip().lower()


def _as_number(v):
    if v is None:
        return 0.0
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip()
    if not s:
        return 0.0
    try:
        return float(s)
    except ValueError:
        return 0.0


def read_weekly_series_by_label(ws, label):
    """Read a week->value mapping from a sheet.

    Supports either:
      - A tabular layout with a header row containing columns 'Week' and <label>
        and week numbers listed down the 'Week' column.
      - A horizontal layout where column A has the <label> and week numbers are in
        the header row (not present in the provided workbook, but supported).
    """

    label_n = _norm(label)

    # First, look for a header row that contains both 'week' and the label.
    header_row = None
    week_col = None
    val_col = None

    for r in range(1, ws.max_row + 1):
        row_vals = [ws.cell(r, c).value for c in range(1, ws.max_column + 1)]
        norms = [_norm(v) for v in row_vals]
        if "week" in norms and label_n in norms:
            header_row = r
            week_col = norms.index("week") + 1
            val_col = norms.index(label_n) + 1
            break

    if header_row is not None:
        out = {}
        for r in range(header_row + 1, ws.max_row + 1):
            wk = ws.cell(r, week_col).value
            if wk is None or _norm(wk) == "":
                continue
            try:
                wk_i = int(float(wk))
            except Exception:
                continue
            out[wk_i] = _as_number(ws.cell(r, val_col).value)
        return out

    # Fallback: horizontal layout. Find the label in column A.
    label_row = None
    for r in range(1, ws.max_row + 1):
        if _norm(ws.cell(r, 1).value) == label_n:
            label_row = r
            break

    if label_row is None:
        raise ValueError(f"Could not locate series for label '{label}' in sheet '{ws.title}'")

    # Assume row 1 contains week numbers across columns.
    out = {}
    for c in range(2, ws.max_column + 1):
        wk = ws.cell(1, c).value
        try:
            wk_i = int(float(wk))
        except Exception:
            continue
        out[wk_i] = _as_number(ws.cell(label_row, c).value)
    return out


def r2(x):
    # Stable-ish rounding to 2 decimals for binary floats.
    return round(float(x) + 1e-12, 2)


def main():
    if not INPUT_XLSX.exists():
        raise FileNotFoundError(str(INPUT_XLSX))

    wb = openpyxl.load_workbook(INPUT_XLSX, data_only=True)

    dye_ws = wb["Dye"]
    adj_ws = wb["Adjust"]

    dye_demand = read_weekly_series_by_label(dye_ws, "Dye Demand (Std Hrs)")
    demand_adj = read_weekly_series_by_label(adj_ws, "Demand Adjustment (Std Hrs)")

    effective_demand = {}
    for w in range(3, 52):
        effective_demand[w] = _as_number(dye_demand.get(w)) + _as_number(demand_adj.get(w))

    # Simulate deterministic policy for weeks 3-51.
    rows = []

    calc_start = 598.24 - effective_demand[3]
    for w in range(3, 52):
        scheduled_demand = effective_demand[w]
        start_past_due = max(0.0, calc_start)

        if start_past_due > 0.01:
            if calc_start + scheduled_demand - 18 * 5 <= 0:
                days_worked = 5
            elif calc_start + scheduled_demand - 18 * 6 <= 0:
                days_worked = 6
            else:
                days_worked = 6
        else:
            if scheduled_demand <= 72:
                days_worked = 4
            else:
                days_worked = 5

        weekly_capacity = 18 * days_worked
        end_backlog = calc_start + scheduled_demand - weekly_capacity
        overtime = 10 * max(0, days_worked - 4)

        rows.append(
            {
                "week": int(w),
                "days_worked": int(days_worked),
                "scheduled_demand": r2(scheduled_demand),
                "weekly_capacity": r2(weekly_capacity),
                "start_past_due": r2(start_past_due),
                "end_backlog": r2(end_backlog),
                "overtime": r2(overtime),
            }
        )

        calc_start = end_backlog

    # Write plan workbook.
    out_wb = Workbook()
    ws = out_wb.active
    ws.title = "Plan"

    headers = [
        "Week",
        "Days Worked",
        "Scheduled Demand (Std Hrs)",
        "Weekly Capacity (Std Hrs)",
        "Start of Week Past Due (Std Hrs)",
        "End of Week Backlog/Buffer (Std Hrs)",
        "Overtime Hours",
    ]
    ws.append(headers)

    for r in rows:
        ws.append(
            [
                r["week"],
                r["days_worked"],
                r["scheduled_demand"],
                r["weekly_capacity"],
                r["start_past_due"],
                r["end_backlog"],
                r["overtime"],
            ]
        )

    out_wb.save(OUT_PLAN_XLSX)

    # Write summary.
    first_week_5 = "N/A"
    first_week_4 = "N/A"
    for r in rows:
        if first_week_5 == "N/A" and r["days_worked"] == 5:
            first_week_5 = str(r["week"])
        if first_week_4 == "N/A" and r["days_worked"] == 4:
            first_week_4 = str(r["week"])

    summary = (
        f"First_Week_5_Days: {first_week_5}\n"
        f"First_Week_4_Days: {first_week_4}\n"
        f"Summary: Plan ramps days worked as backlog clears; first 5-day week is {first_week_5} and first 4-day week is {first_week_4}. Capacity is 18 std hrs/day with overtime at 10 hrs/day beyond 4 days."
    )

    # Ensure <= 60 words and <= 3 sentences for the Summary: line.
    # (The first two lines are fixed; only validate the summary text constraints.)
    summary_line = summary.splitlines()[2]
    summary_text = summary_line.replace("Summary:", "", 1).strip()
    word_count = len([w for w in summary_text.split() if w])
    if word_count > 60:
        raise ValueError(f"Summary too long: {word_count} words")
    sentence_count = len([s for s in summary_text.replace("!", ".").replace("?", ".").split(".") if s.strip()])
    if sentence_count > 3:
        raise ValueError(f"Summary too many sentences: {sentence_count}")

    OUT_SUMMARY_TXT.write_text(summary, encoding="utf-8")

    # Validation
    plan_wb = openpyxl.load_workbook(OUT_PLAN_XLSX, data_only=True)
    plan_ws = plan_wb["Plan"]
    all_rows = []
    for r in plan_ws.iter_rows(values_only=True):
        all_rows.append(list(r))

    print("\nValidation: Plan sheet preview")
    print("First 5 rows:")
    for r in all_rows[:5]:
        print(r)

    print("Last 3 rows:")
    for r in all_rows[-3:]:
        print(r)

    summary_contents = OUT_SUMMARY_TXT.read_text(encoding="utf-8")
    print("\nValidation: Summary file contents")
    print(summary_contents)

    data_row_count = plan_ws.max_row - 1
    print(f"\nValidation: Plan data row count = {data_row_count}")

    weeks_in_sheet = [plan_ws.cell(r, 1).value for r in range(2, plan_ws.max_row + 1)]
    expected_weeks = list(range(3, 52))
    if weeks_in_sheet != expected_weeks:
        raise ValueError(
            f"Week column mismatch. Expected {expected_weeks[:5]}..{expected_weeks[-5:]}, got {weeks_in_sheet[:5]}..{weeks_in_sheet[-5:]}"
        )
    print("Validation: Week column is continuous 3..51")

    unique_days = {plan_ws.cell(r, 2).value for r in range(2, plan_ws.max_row + 1)}
    print(f"Validation: Unique Days Worked values = {sorted(unique_days)}")

    allowed = {4, 5, 6}
    if not unique_days.issubset(allowed):
        raise ValueError(f"Unexpected Days Worked values: {sorted(unique_days - allowed)}")

    if data_row_count != 49:
        raise ValueError(f"Expected 49 data rows, got {data_row_count}")


if __name__ == "__main__":
    main()

